cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int K, int stride, int padding, int dilation,
    int groups)
{
    constexpr int Threads = 128;
    constexpr int PVec    = 2;
    constexpr int CoChunk = 4;

    const int tid = threadIdx.x;
    const int n = blockIdx.z;
    const int co_tile = blockIdx.y;
    const int co_base = co_tile * CoChunk;

    const int CinPerGroup = Cin / groups;
    const int CoPerGroup  = Cout / groups;

    const int K3 = K * K * K;

    const int64_t sXn = (int64_t)Cin * D * H * Win;
    const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;

    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, D, H, Win),
        make_stride((int64_t)D * H * Win, (int64_t)H * Win, (int64_t)Win, (int64_t)1));

    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, Dout, Hout, Wout),
        make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, CoPerGroup, K, K, K),
        make_stride((int64_t)CoPerGroup * K3, (int64_t)K3, (int64_t)K * K, (int64_t)K, (int64_t)1));

    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);
    auto sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(Int<CoChunk>{}, K3),
        make_stride(K3, 1));

    const int64_t P_total = (int64_t)Dout * Hout * Wout;
    const int64_t PTile   = (int64_t)Threads * PVec;
    const int64_t p_block = (int64_t)blockIdx.x * PTile;

    int  od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
    bool pvalid[PVec];

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int64_t p = p_block + tid + (int64_t)i * Threads;
        if (p < P_total) {
            int64_t od  = p / ((int64_t)Hout * Wout);
            int64_t rem = p - od * ((int64_t)Hout * Wout);
            int64_t oh  = rem / Wout;
            int64_t ow  = rem - oh * Wout;
            od_arr[i] = (int)od;
            oh_arr[i] = (int)oh;
            ow_arr[i] = (int)ow;
            pvalid[i] = true;
        } else {
            od_arr[i] = oh_arr[i] = ow_arr[i] = 0;
            pvalid[i] = false;
        }
    }

    int  co_local_arr[CoChunk];
    int  ci_offset_arr[CoChunk];
    bool co_valid[CoChunk];

    #pragma unroll
    for (int cc = 0; cc < CoChunk; ++cc) {
        int co = co_base + cc;
        if (co < Cout) {
            int g = co / CoPerGroup;
            co_local_arr[cc]  = co % CoPerGroup;
            ci_offset_arr[cc] = g * CinPerGroup;
            co_valid[cc] = true;
        } else {
            co_local_arr[cc]  = 0;
            ci_offset_arr[cc] = 0;
            co_valid[cc] = false;
        }
    }

    float acc[CoChunk][PVec];
    #pragma unroll
    for (int cc = 0; cc < CoChunk; ++cc) {
        int co = co_base + cc;
        float bval = 0.0f;
        if (Bp != nullptr && co < Cout) bval = (float)Bp[co];
        #pragma unroll
        for (int i = 0; i < PVec; ++i) acc[cc][i] = bval;
    }

    for (int ci_local = 0; ci_local < CinPerGroup; ++ci_local) {
        for (int idx = tid; idx < CoChunk * K3; idx += Threads) {
            int cc    = idx / K3;
            int k_lin = idx % K3;
            T wval = T(0);
            if (co_valid[cc]) {
                int kd  = k_lin / (K * K);
                int rem = k_lin - kd * K * K;
                int kh  = rem / K;
                int kw  = rem - kh * K;
                int ci  = ci_offset_arr[cc] + ci_local;
                wval = mW(ci, co_local_arr[cc], kd, kh, kw);
            }
            sW(cc, k_lin) = wval;
        }
        __syncthreads();

        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
            if (!pvalid[i]) continue;
            int od = od_arr[i], oh = oh_arr[i], ow = ow_arr[i];

            for (int k_lin = 0; k_lin < K3; ++k_lin) {
                int kd  = k_lin / (K * K);
                int rem = k_lin - kd * K * K;
                int kh  = rem / K;
                int kw  = rem - kh * K;

                int vd = od + padding - kd * dilation;
                if (vd < 0 || (vd % stride) != 0) continue;
                int id = vd / stride;
                if (id < 0 || id >= D) continue;

                int vh = oh + padding - kh * dilation;
                if (vh < 0 || (vh % stride) != 0) continue;
                int ih = vh / stride;
                if (ih < 0 || ih >= H) continue;

                int vw = ow + padding - kw * dilation;
                if (vw < 0 || (vw % stride) != 0) continue;
                int iw = vw / stride;
                if (iw < 0 || iw >= Win) continue;

                #pragma unroll
                for (int cc = 0; cc < CoChunk; ++cc) {
                    if (!co_valid[cc]) continue;
                    int ci = ci_offset_arr[cc] + ci_local;
                    float xval = (float)mX(ci, id, ih, iw);
                    float wval = (float)sW(cc, k_lin);
                    acc[cc][i] += xval * wval;
                }
            }
        }
        __syncthreads();
    }

    #pragma unroll
    for (int cc = 0; cc < CoChunk; ++cc) {
        if (!co_valid[cc]) continue;
        int co = co_base + cc;
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
            if (!pvalid[i]) continue;
            mY(co, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
        }
    }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int kernel_size,
                                        int stride,
                                        int padding,
                                        int output_padding,
                                        int dilation,
                                        int groups) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(w.is_cuda(), "w must be CUDA");
    if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
    if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
    TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, K, K, K]");

    auto x_c = x.contiguous();
    auto w_c = w.contiguous();

    int N   = (int)x_c.size(0);
    int Cin = (int)x_c.size(1);
    int D   = (int)x_c.size(2);
    int H   = (int)x_c.size(3);
    int Win = (int)x_c.size(4);

    int CoPerGroup = (int)w_c.size(1);
    int Cout = CoPerGroup * groups;
    int K = kernel_size;

    TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
    TORCH_CHECK(w_c.size(2) == K && w_c.size(3) == K && w_c.size(4) == K, "kernel size mismatch");

    int Dout = (D - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int Hout = (H - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;

    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (b.has_value()) {
        b_c = b.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

    constexpr int Threads = 128;
    constexpr int PVec = 2;
    constexpr int CoChunk = 4;

    int64_t P_total = (int64_t)Dout * Hout * Wout;
    int64_t PTile   = (int64_t)Threads * PVec;

    dim3 block(Threads);
    dim3 grid(
        (unsigned)((P_total + PTile - 1) / PTile),
        (unsigned)((Cout + CoChunk - 1) / CoChunk),
        (unsigned)N
    );

    int K3 = K * K * K;
    size_t smem_size = (size_t)CoChunk * K3 * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv_transpose3d_kernel<float><<<grid, block, smem_size, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        N, Cin, D, H, Win,
        Cout, Dout, Hout, Wout,
        K, stride, padding, dilation,
        groups
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with a square kernel, implemented with a single
    custom CUDA kernel using CuTe for tensor addressing and shared-memory
    weight caching.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        CoPerGroup = self.out_channels // self.groups

        # Weight shape matches nn.ConvTranspose3d: (Cin, Cout/groups, K, K, K)
        self.weight = nn.Parameter(torch.empty(self.in_channels, CoPerGroup, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.kernel_size),
            int(self.stride),
            int(self.padding),
            int(self.output_padding),
            int(self.dilation),
            int(self.groups),
        )

