            int64_t rem = p - od * ((int64_t)Hout * Wout);
            int64_t oh  = rem / Wout;
            int64_t ow  = rem - oh * Wout;
            od_arr[i] = (int)od;
            oh_arr[i] = (int)oh;
            ow_arr[i] = (int)ow;
            pvalid[i] = true;
        } else {
            od_arr[i] = oh_arr[i] = ow_arr[i] = 0;
            pvalid[i] = false;
